import Foundation

// The evidence bundle is built from structure, never by cleaning text up. Every value in it is either generated by
// sideload, or an Apple string admitted whole by `MessageFilter`, or left out and counted. Nothing is rewritten, so
// nothing is over-masked and no variant of a name can slip past a pattern.

/// Words that identify the people and machines involved, as plain lowercase ASCII strings.
struct SubjectTokens: Equatable, Sendable {
    /// Lowercase ASCII letters and digits only; at least two characters.
    var tokens: [String] = []
    /// The device's UDID and CoreDevice ID as written, for the whole-body ID check.
    var ids: [String] = []

    /// Hardware and OS words a device name is usually built from; they identify nobody and would only block Apple's text.
    static let generic: Set<String> = [
        "iphone", "ipad", "ipod", "mac", "macbook", "pro", "air", "mini", "imac", "studio", "apple", "tv", "watch",
        "local", "development", "distribution", "developer",
    ]

    /// NFKD, combining marks removed, lowercase, ASCII letters and digits only (`Zoë` is `zoe`).
    static func fold(_ s: String) -> String {
        var out = ""
        for scalar in s.decomposedStringWithCompatibilityMapping.unicodeScalars {
            switch scalar.properties.generalCategory {
            case .nonspacingMark, .spacingMark, .enclosingMark: continue
            default: break
            }
            let c = Character(scalar)
            guard c.isASCII, c.isLetter || c.isNumber else { continue }
            out.append(contentsOf: c.lowercased())
        }
        return out
    }

    /// The pieces of a name: split at anything that is not a letter or digit, then folded.
    static func words(_ s: String) -> [String] {
        s.split(whereSeparator: { !($0.isLetter || $0.isNumber) }).map { fold(String($0)) }.filter { !$0.isEmpty }
    }

    /// `Kind: Person Name (PERSONALID)`, the signing identity common-name shape; shared with `InstallLogScrubber`.
    static let identityShape = try! NSRegularExpression(pattern: #"^[^:]*:\s*(.+?)\s*\(([A-Z0-9]{10})\)\s*$"#)

    /// Everything that must not appear: device names and hostnames (split on `-._ ` and punctuation), the login,
    /// the full name's words, the person's name in each signing identity's common name, this Mac's computer name
    /// and local host name, and the home folder's name. Each folded, with a copy minus a trailing `s`.
    static func make(_ subjects: EvidenceSubjects) -> SubjectTokens {
        var sources = subjects.names + [subjects.login, subjects.fullName, subjects.computerName, subjects.localHostName]
        if let home = subjects.homeName { sources.append(home) }
        for cn in subjects.identityNames {
            let ns = cn as NSString
            if let m = identityShape.firstMatch(in: cn, range: NSRange(location: 0, length: ns.length)) {
                sources.append(ns.substring(with: m.range(at: 1)))
            } else {
                // The personal ID is a 10-character code that looks like the team ID; it is not a person's name.
                sources.append(contentsOf: words(cn).filter { !($0.count == 10 && $0.contains(where: \.isNumber)) })
            }
        }
        var found: [String] = []
        func add(_ t: String) {
            if t.count >= 2, !generic.contains(t), !found.contains(t) { found.append(t) }
        }
        for source in sources {
            for word in words(source) {
                add(word)
                if word.hasSuffix("s") { add(String(word.dropLast())) }
            }
        }
        return SubjectTokens(tokens: found.sorted(), ids: subjects.ids.filter { !$0.isEmpty })
    }

    /// Stricter, for the short identifiers we keep without a vocabulary (domain, `LegacyErrorString`, outcome): any
    /// subject token of any length, or a device ID, anywhere in the letters and digits run together.
    func appearsAnywhere(in text: String) -> Bool {
        let squashed = Self.fold(text)
        if tokens.contains(where: { squashed.contains($0) }) { return true }
        return ids.contains { $0.count >= 8 && squashed.contains(Self.fold($0)) }
    }

    /// True when the text mentions a subject (or a device ID): a token of four or more characters anywhere in its
    /// letters and digits run together (so `Jane's iPhone`, `Janes-iPhone` and `jane%27s` all contain `jane`), or a shorter token as a
    /// whole word (so `Den` does not trip over `identity`).
    func appears(in text: String) -> Bool {
        let squashed = Self.fold(text)
        // A device ID anywhere, with or without its hyphens, in any case.
        for id in ids where id.count >= 8 && squashed.contains(Self.fold(id)) { return true }
        var shortWords: Set<String> = []
        for run in text.split(whereSeparator: { !($0.isLetter || $0.isNumber) }) {
            let w = Self.fold(String(run))
            shortWords.insert(w)
            if w.hasSuffix("s") { shortWords.insert(String(w.dropLast())) }
        }
        for t in tokens {
            if t.count >= 4 ? squashed.contains(t) : shortWords.contains(t) { return true }
        }
        return false
    }
}

enum MessageFilter {
    static let maxLength = 512
    /// A longer input is not even normalised.
    private static let maxInput = 4096

    private static let allowed: Set<Character> = Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 .,;:()'-")

    /// NFKC, curly apostrophes straightened, whitespace runs collapsed to one space, trimmed.
    static func normalize(_ raw: String) -> String {
        var s = raw.precomposedStringWithCompatibilityMapping
        for c in ["\u{2019}", "\u{2018}", "\u{02BC}"] { s = s.replacingOccurrences(of: c, with: "'") }
        return s.split(whereSeparator: \.isWhitespace).joined(separator: " ")
    }

    /// The message as normalised when every character and every word is on the fixed lists and no subject token
    /// appears in it; otherwise nil. The quotes around exactly `Canary` or the bundle ID are allowed, and the bundle
    /// ID counts as one token.
    static func admit(_ raw: String, tokens: SubjectTokens, bundleId: String? = nil) -> String? {
        guard raw.utf16.count <= maxInput else { return nil }
        let s = normalize(raw)
        guard !s.isEmpty, s.utf16.count <= maxLength else { return nil }

        var rest = s
        let literals = ["Canary"] + (bundleId.map { $0.isEmpty ? [] : [$0] } ?? [])
        for literal in literals {
            for open in ["\u{201C}", "\""] {
                for close in ["\u{201D}", "\""] {
                    rest = rest.replacingOccurrences(of: open + literal + close, with: " ")
                }
            }
        }
        if let bundleId, !bundleId.isEmpty { rest = rest.replacingOccurrences(of: bundleId, with: " ") }

        guard rest.allSatisfy({ allowed.contains($0) }) else { return nil }
        for run in rest.split(whereSeparator: { !($0.isASCII && ($0.isLetter || $0.isNumber || $0 == "'")) }) {
            guard isKnown(String(run).lowercased()) else { return nil }
        }
        if tokens.appears(in: rest) { return nil }
        return s
    }

    private static func isKnown(_ run: String) -> Bool {
        if EvidenceVocabulary.words.contains(run) { return true }
        if run.wholeMatch(of: /0x[0-9a-f]{1,8}/) != nil || run.wholeMatch(of: /[0-9]{1,10}/) != nil { return true }
        return false
    }
}

/// The chain of errors devicectl reports, reduced to a closed set of fields.
enum ErrorChain {
    static let maxDepth = 8
    static let maxNodes = 16
    static let maxStderrLines = 20
    /// More stderr than this is counted, not read.
    static let stderrScanLimit = 2000
    /// Error domains Apple's tools use for an install failure (the 2026-10-20 capture plus `MobileDeviceErrorDomain`).
    /// Kept exactly, without the subject-token check; `EvidenceSchema.knownDomains` is the verifier's own copy.
    static let knownDomains: Set<String> = [
        "com.apple.dt.CoreDeviceError", "com.apple.dt.MobileDeviceErrorDomain", "IXUserPresentableErrorDomain",
        "MIInstallerErrorDomain",
    ]

    struct CodeSignature: Equatable {
        var code: String
        var message: String?
        var appBundle: String?
    }

    struct Node: Equatable {
        var depth: Int
        var domain: String?
        var code: Int
        var codeHex: String?
        var description: String?
        var failureReason: String?
        var recoverySuggestion: String?
        var legacyErrorString: String?
        var libMISErrorNumber: String?
        var codeSignature: CodeSignature?
    }

    struct Reduction: Equatable {
        var outcome: String?
        var nodes: [Node] = []
        var stderr: [String] = []
        var omittedNodes = 0
        var omittedMessages = 0
        var omittedStderrLines = 0
    }

    /// `json` is the `devicectl --json-output` document. Fields not named here are never read.
    static func reduce(json: JSONValue?, stderr: String, tokens: SubjectTokens, bundleId: String?) -> Reduction {
        var out = Reduction()
        if case .object(let top)? = json {
            if case .object(let info)? = top["info"], case .string(let o)? = info["outcome"] {
                if ["failed", "success", "succeeded"].contains(o), keepable(o, tokens) {
                    out.outcome = o
                } else {
                    out.omittedMessages += 1
                }
            }
            if let error = top["error"] { visit(error, depth: 0, tokens, bundleId, &out) }
        }
        reduceStderr(stderr, tokens, bundleId, &out)
        return out
    }

    /// A run of nine or more hex digits mixing letters and digits: the shape of an ID or a hash.
    private static func hasHexRun(_ s: String) -> Bool {
        var run = 0, digit = false, letter = false
        for c in s + " " {
            if c.isASCII, c.isHexDigit {
                run += 1
                if c.isNumber { digit = true } else { letter = true }
            } else {
                if run >= 9, digit, letter { return true }
                run = 0
                digit = false
                letter = false
            }
        }
        return false
    }

    /// A short identifier of Apple's choosing that is safe to keep: no subject word, no ID shape.
    private static func keepable(_ s: String, _ tokens: SubjectTokens) -> Bool {
        !tokens.appearsAnywhere(in: s) && !hasHexRun(s)
    }

    // MARK: nodes

    private static func intValue(_ v: JSONValue?) -> Int? {
        guard case .number(let n)? = v, n == n.rounded(), abs(n) < 9_007_199_254_740_992 else { return nil }
        return Int(n)
    }

    /// `{string: x}` or a bare string.
    private static func text(_ v: JSONValue?) -> String? {
        switch v {
        case .string(let s)?: return s
        case .object(let o)?: if case .string(let s)? = o["string"], o.count == 1 { return s } else { return nil }
        default: return nil
        }
    }

    /// `{error: x}` unwrapped, else the value itself.
    private static func unwrap(_ v: JSONValue) -> JSONValue {
        if case .object(let o) = v, case let inner? = o["error"], o.count == 1 { return inner }
        return v
    }

    private static func visit(_ raw: JSONValue, depth: Int, _ tokens: SubjectTokens, _ bundleId: String?, _ out: inout Reduction) {
        guard case .object(let obj) = raw, case .string(let domain)? = obj["domain"], let code = intValue(obj["code"]) else {
            out.omittedNodes += 1
            return
        }
        guard depth <= maxDepth, out.nodes.count < maxNodes else {
            out.omittedNodes += 1
            return
        }
        var node = Node(
            depth: depth, domain: nil, code: code,
            // Only codes that fit 32 bits (signed or unsigned) have an honest 0x%08x form.
            codeHex: (Int(Int32.min)...Int(UInt32.max)).contains(code)
                ? String(format: "0x%08x", UInt32(truncatingIfNeeded: Int64(code))) : nil)
        // A known Apple domain is a fixed string, so it is kept whole even when a short subject token (`ice`) happens to
        // sit inside it; any other domain must pass the subject check.
        if knownDomains.contains(domain)
            || (domain.utf16.count <= 96 && domain.wholeMatch(of: /[A-Za-z][A-Za-z0-9]*(\.[A-Za-z0-9]+)*/) != nil && keepable(domain, tokens))
        {
            node.domain = domain
        } else {
            out.omittedMessages += 1
        }
        var userInfo: [String: JSONValue] = [:]
        if case .object(let u)? = obj["userInfo"] { userInfo = u }

        func message(_ key: String) -> String? {
            guard let value = userInfo[key] else { return nil }
            if let s = text(value), let admitted = MessageFilter.admit(s, tokens: tokens, bundleId: bundleId) {
                return admitted
            }
            out.omittedMessages += 1
            return nil
        }
        // The signature template carries a path; it is never emitted, only its parts.
        if let value = userInfo["NSLocalizedDescription"], let s = text(value),
            let m = MessageFilter.normalize(s).wholeMatch(of: /Failed to verify code signature of (\S+) : (0x[0-9a-fA-F]{8}) \((.+)\)/)
        {
            let sigMessage = MessageFilter.admit(String(m.3), tokens: tokens, bundleId: bundleId)
            if sigMessage == nil { out.omittedMessages += 1 }
            let last = m.1.split(separator: "/", omittingEmptySubsequences: true).last.map(String.init)
            node.codeSignature = CodeSignature(
                code: String(m.2).lowercased(), message: sigMessage, appBundle: last == "Canary.app" ? "Canary.app" : nil)
        } else {
            node.description = message("NSLocalizedDescription")
        }
        node.failureReason = message("NSLocalizedFailureReason")
        node.recoverySuggestion = message("NSLocalizedRecoverySuggestion")

        if let legacy = text(userInfo["LegacyErrorString"]) {
            if legacy.utf16.count <= 64, legacy.wholeMatch(of: /[A-Za-z][A-Za-z0-9]{0,63}/) != nil, keepable(legacy, tokens) {
                node.legacyErrorString = legacy
            } else {
                out.omittedMessages += 1
            }
        }
        if let value = userInfo["LibMISErrorNumber"] {
            node.libMISErrorNumber = libMISNumber(value)
            if node.libMISErrorNumber == nil { out.omittedMessages += 1 }
        }
        out.nodes.append(node)

        if let under = userInfo["NSUnderlyingError"] {
            visit(unwrap(under), depth: depth + 1, tokens, bundleId, &out)
        }
        if case .array(let many)? = userInfo["NSMultipleUnderlyingErrorsKey"] {
            for item in many { visit(unwrap(item), depth: depth + 1, tokens, bundleId, &out) }
        }
    }

    /// An integer, bare or as `{int: n}` / `{uint: n}`, as a decimal string, only when a double holds it exactly
    /// (below 2^53; 2^53 itself may be a rounded neighbour). A larger value cannot be recovered from the parsed document, so it is left out rather than
    /// written with invented digits; `codeSignature.code` and `codeHex` carry the status.
    private static func libMISNumber(_ v: JSONValue?) -> String? {
        var inner = v
        if case .object(let o)? = v, o.count == 1 { inner = o["int"] ?? o["uint"] }
        guard case .number(let n)? = inner, n == n.rounded(), abs(n) < 9_007_199_254_740_992 else { return nil }
        return String(Int64(n))
    }

    // MARK: stderr

    private static func reduceStderr(_ stderr: String, _ tokens: SubjectTokens, _ bundleId: String?, _ out: inout Reduction) {
        var seen = Set<String>()
        var scanned = 0
        for line in stderr.split(whereSeparator: \.isNewline) {
            // Blank lines and separator rules (`-----`) carry nothing: dropped, not counted.
            guard line.contains(where: { $0.isLetter || $0.isNumber }) else { continue }
            scanned += 1
            guard scanned <= stderrScanLimit else {
                out.omittedStderrLines += 1
                continue
            }
            guard let admitted = MessageFilter.admit(String(line), tokens: tokens, bundleId: bundleId) else {
                out.omittedStderrLines += 1
                continue
            }
            guard seen.insert(admitted).inserted else { continue }
            if out.stderr.count < maxStderrLines { out.stderr.append(admitted) } else { out.omittedStderrLines += 1 }
        }
    }
}
